function mousePressed()
{
 particles.add(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),particles.size()+1,true));
}

class Particle
{
  pos, vel, acc;
  Id;
  live;

  constructor(x, y,nid,llive)
  {
    pos = new PVector(x, y);
    vel = new PVector(0, 0);
    acc = new PVector(0, 0);
    Id=nid;
    live=llive;
  }

  function submitForce(p)
  {
    //let d = sq(pos.dist(p.pos));
    let force;
    let x,y;
    force = new PVector(0,0);
    force.y=-0.01;
    force.x=0;   
    acc.add(force);  
  }

  function display()
  {
    noStroke();
    if(Id==1)
      {fill(255,0,0);}
    else
      if(Id%2==0)
        {fill(255, 255, 0, 200);}
      else
        {fill(0,0,255);}

    fill(255,255,255);
    ellipse(pos.x, pos.y, 8, 8);
    stroke(255,0,0);
    strokeWeight(5); 
  }

  function update()
  {
    acc.limit(MAX_ACC);
    vel.add(acc);
    vel.limit(MAX_VEL);
    acc = new PVector(0, 0);
    pos.add(vel);
    pos.x=pos.x+random(-4,4);

    if(pos.y<height-540)
      {
        live=false;        
      }
     if(pos.x < 160)
      {
        vel.x *= -1;
        pos.x =pos.x+ vel.x+2;
      }
    if(pos.x >= width-160)
      {
        vel.x *= -1;
        pos.x = pos.x+vel.x-2;
      }
    if(pos.y >= 447)
      {
        vel.y *= -1;
        pos.y =pos.y+ vel.y-2;
      }
  }
}

